 CREATE OR REPLACE FUNCTION public.getassociatepetitionslist(v_intake character varying, pagenumber bigint, pagesize bigint)                                                                                                              
  RETURNS TABLE(totalcount bigint, petitionid character varying, intakeservicerequestpetitionid uuid, intakenumber character varying, associatedpetition json, associatedcomplaint json, complaint json)                                  
  LANGUAGE plpgsql                                                                                                                                                                                                                        
 AS $function$                                                                                                                                                                                                                            
                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                          
 declare v_pagenumber bigint;                                                                                                                                                                                                             
                                                                                                                                                                                                                                          
 begin                                                                                                                                                                                                                                    
          v_pagenumber := (pagenumber-1)*   10;                                                                                                                                                                                           
                                                                                                                                                                                                                                          
          RETURN QUERY                                                                                                                                                                                                                    
 select count(1) over() as totalcount,  INTSRP.petitionid ,INTSRP.intakeservicerequestpetitionid,INTSRP.intakenumber                                                                                                                      
                                 ,(select json_agg(x) from (select associatedpetitionid, (select IIN.petitionid from intakeservicerequestpetition IIN where IIN.intakeservicerequestpetitionid=associatedpetitionid) as associatepetition 
                         from associatedpetitionsconfig ASPC                                                                                                                                                                              
                         join intakeservicerequestpetition INRP on INRP.intakeservicerequestpetitionid=ASPC.intakeservicerequestpetitionid and INRP.activeflag=1                                                                          
                         where ASPC.activeflag=1 and INRP.intakeservicerequestpetitionid =INTSRP.intakeservicerequestpetitionid  and associatedevalfieldid is null) as X ) as AssociatedPetition,                                         
                                                                                                                                                                                                                                          
                         (select json_agg(x) from (select associatedevalfieldid, (select IIE.complaintid from intakeservicerequestevaluation IIE where IIE.intakeservicerequestevaluationid=associatedevalfieldid) as associatecomplaint  
                         from associatedpetitionsconfig ASPC                                                                                                                                                                              
                         join intakeservicerequestpetition INRP on INRP.intakeservicerequestpetitionid=ASPC.intakeservicerequestpetitionid and INRP.activeflag=1                                                                          
                         where ASPC.activeflag=1 and INRP.intakeservicerequestpetitionid =INTSRP.intakeservicerequestpetitionid and associatedpetitionid  is null ) as X ) as AssociatedComplaint,                                        
                                                                                                                                                                                                                                          
                                 (select json_agg(x) from (select  INTSRE.complaintid as complaintID  ,INTSRE.intakeservicerequestevaluationid ,                                                                                          
                                                                                                                                                                                                                                          
                          (select array_agg(AG.name)  from  allegation AG                                                                                                                                                                 
            join intakeservicerequestevaluationconfig ITSEC  on ITSEC.allegationid=AG.allegationid and AG.activeflag=1                                                                                                                    
            where  ITSEC.intakeservicerequestevaluationid=INTSRE.intakeservicerequestevaluationid and ITSEC.activeflag=1 ) as allegationname,                                                                                             
                    case when INTSRE.unknownrange=0 then to_char(INTSRE.offensedate,'MM/DD/YYYY')                                                                                                                                         
            when INTSRE.unknownrange=1 then '' :: character varying                                                                                                                                                                       
                    when INTSRE.unknownrange=2 then to_char(INTSRE.begindate,'MM/DD/YYYY')|| ' - ' || to_char(INTSRE.enddate,'MM/DD/YYYY')                                                                                                
                    end as offensedate                                                                                                                                                                                                    
                         from intakeservicerequestevaluation INTSRE                                                                                                                                                                       
                          join Intakeservreqevalpetitionconfig INTSREPC on INTSRE.intakeservicerequestevaluationid =INTSREPC.intakeservicerequestevaluationid and INTSREPC.activeflag=1                                                   
                          where INTSREPC.intakeservicerequestpetitionid=INTSRP.intakeservicerequestpetitionid                                                                                                                             
                         -- join intakeservicerequestpetition INTSRP on INTSRP.intakeservicerequestpetitionid =INTSREPC.intakeservicerequestpetitionid and INTSRP.activeflag=1                                                            
                         ) as X ) as COMPLAINT                                                                                                                                                                                            
                                                                                                                                                                                                                                          
                         /*from intakeservicerequestpetition INTSRP where                                                                                                                                                                 
                         INTSRP.intakeservicerequestpetitionid in (select ISRPHC.intakeservicerequestpetitionid from intakeservreqpetitionhearingconfig                                                                                   
                         as ISRPHC join intakeservicerequestcourthearing as ISRCH                                                                                                                                                         
                         on ISRCH.intakeservicerequestcourthearingid = ISRPHC.intakeservicerequestcourthearingid and ISRCH.activeflag=1                                                                                                   
                         where ISRCH.courthearingstatustypekey !='Completed' and ISRPHC.activeflag =1) and */                                                                                                                             
                         /* Associate Complaint ID lists the Petition which has completed Adjudication Hearing. Should not display the Petitions which has completed hearings(Adjudication) issue fixed by Gavaskar 11-01-2019 Start */   
                         from (                                                                                                                                                                                                           
                         select pet.* from intakeservicerequestpetition pet where pet.intakeservicerequestpetitionid in (                                                                                                                 
                                 select ISRPHC.intakeservicerequestpetitionid from intakeservreqpetitionhearingconfig                                                                                                                     
                         as ISRPHC join intakeservicerequestcourthearing as ISRCH                                                                                                                                                         
                         on ISRCH.intakeservicerequestcourthearingid = ISRPHC.intakeservicerequestcourthearingid and ISRCH.activeflag=1                                                                                                   
                         where ISRCH.courthearingstatustypekey !='Completed' and ISRPHC.activeflag =1                                                                                                                                     
                         and ISRPHC.intakeservicerequestpetitionid = pet.intakeservicerequestpetitionid and pet.activeflag = 1                                                                                                            
                         ) union all                                                                                                                                                                                                      
                         select pet.* from intakeservicerequestpetition pet left join intakeservreqpetitionhearingconfig as ISRPHC                                                                                                        
                         on ISRPHC.intakeservicerequestpetitionid = pet.intakeservicerequestpetitionid and ISRPHC.activeflag = 1                                                                                                          
                         where ISRPHC.intakeservicerequestpetitionid is null and pet.activeflag = 1                                                                                                                                       
                         )                                                                                                                                                                                                                
                         /* Associate Complaint ID lists the Petition which has completed Adjudication Hearing. Should not display the Petitions which has completed hearings(Adjudication) issue fixed by Gavaskar 11-01-2019 End */     
                         as INTSRP where                                                                                                                                                                                                  
                         (INTSRP.petitionstatustypekey='OP' or INTSRP.petitionstatustypekey='SCH') and INTSRP.intakenumber in (                                                                                                           
                         select INTSR.intakenumber from intakeservicerequest INTSR                                                                                                                                                        
                         join intakeservicerequestactor INSRA on INSRA.intakeserviceid=INTSR.intakeserviceid and INSRA.activeflag=1                                                                                                       
                         join actor ACC on ACC.actorid=INSRA.actorid and ACC.activeflag=1                                                                                                                                                 
 --                      join person                                                                                                                                                                                                      
                         where  INTSR.intakenumber!=v_intake and                                                                                                                                                                          
                           ACC.personid in                                                                                                                                                                                                
                         (                                                                                                                                                                                                                
                         select P.personid from intakeservicerequest ISR                                                                                                                                                                  
                         join intakeservicerequestactor ISRA on ISRA.intakeserviceid=ISR.intakeserviceid and ISRA.activeflag=1                                                                                                            
                         left join actor AC on ISRA.actorid = AC.actorid  and AC.activeflag=1                                                                                                                                             
                         left join person P on P.personid = AC.personid and P.activeflag=1                                                                                                                                                
                         where ISR.intakenumber=v_intake and ISR.activeflag=1 and Lower(AC.actortype) = 'youth'))                                                                                                                         
         --              limit pagesize offset v_pagenumber                                                                                                                                                                               
                 ;                                                                                                                                                                                                                        
                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                          
                         end                                                                                                                                                                                                              
                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                          
 $function$                                                                                                                                                                                                                               

